INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261110-senate-counts', 'peltola-leads-sullivan-2517-votes-alaska-colom-hyde-smith-mississippi-deadline-nov-10', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Peltola''s lead over Sullivan grows to 2,517 votes in Alaska, and Mississippi reaches its ballot-cure deadline with Colom ahead by about 2,500', 'Alaska expected a larger count on Tuesday, Nov. 10, and both campaigns are fighting in court over rejected absentee ballots. Mississippi counties must certify by Friday, Nov. 13.', 'Democrat Mary Peltola led Republican Sen. Dan Sullivan by 2,517 first-choice votes in Alaska''s Senate race in the Division of Elections'' unofficial report at 2:55 p.m. on Monday, Nov. 9, The Alaska Story reported. The count stood at 106,321 (48.47%) to 103,804 (47.33%). The division added 4,947 votes on Monday.

## Alaska

No candidate has passed 50% of first-choice votes, so the race will go to a ranked-choice tabulation, according to The Alaska Story. The division was expected to release its seven-day ballot count on Tuesday, Nov. 10, Your Alaska Link reported. A Fox News report published earlier on Monday put Peltola''s lead at about 600 votes; the division''s afternoon report shows the larger margin.

The race has also moved to court. Peltola''s campaign sued the Division of Elections on Friday, Nov. 6, seeking records of absentee ballots that were preliminarily rejected, Fox News reported. Sullivan''s campaign moved to intervene on Monday, and a spokesman said the lawsuit tries to "rig the system." The division said it would be improper to share the data before voters themselves are notified.

## Mississippi

Democrat Scott Colom led Republican Sen. Cindy Hyde-Smith by a little over 2,500 votes, 49.1% to 48.8%, with just over 97% of votes counted as of Monday morning, Nov. 9, Newsweek reported. The race had not been called.

Tuesday, Nov. 10, is the last day for mail ballots postmarked by Election Day to arrive and for affidavit voters to show ID at their circuit clerk''s office. Harrison County''s election commission was set to decide on its 1,448 affidavit ballots on Nov. 10, and DeSoto County tentatively planned to count about 2,100 affidavits that evening, the Mississippi Free Press reported. Counties must certify by Friday, Nov. 13. Mississippi has no recount law, so any challenge would go to court, Newsweek noted. Hyde-Smith''s campaign said "this election is not over."', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/d/d8/Juneau,_Alaska_from_the_water,_between_1886_and_1896_(AL%2BCA_6907).jpg', 'Juneau, Alaska, seen from the water, between 1886 and 1896 (file). Photo: University of Washington Libraries via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-10.sql', 8, 0, 'newsroom-assistant', '2026-11-10T10:45:00.000Z', '2026-11-10T10:45:00.000Z');
