INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261110-immigration-deal', 'white-house-trump-immigration-deal-democrats-never-said-amnesty-base-backlash', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'White House says Trump "never said the word amnesty" after he floated an immigration deal with Democrats', 'Officials on Monday, Nov. 9, would not rule out a deal or say what it might include. Some of Trump''s supporters called the idea a betrayal.', 'The White House on Monday, Nov. 9, defended President Trump''s openness to an immigration deal with Democrats while rejecting the label "amnesty," Fox News reported.

In his *60 Minutes* interview, which aired on Sunday, Nov. 8, Trump said he would "love to do something on immigration." He described people who have lived in the U.S. illegally for 10 to 15 years, worked, paid taxes and committed no other crimes as a group he would be willing to "work a deal" on, according to Fox News. The interview was taped before Stephen Miller was named White House chief of staff.

## The White House response

"The President never said the word amnesty," a White House official told Fox News, pointing to the administration''s enforcement record. Another official said, "We want Democrats to show their cards." The White House would not rule out a deal, and would not say what one might include.

## Mixed reaction on the right

Rep. Maria Salazar, R-Fla., praised the comments and said they match her Dignity Act, which would give legal status to some long-term residents who pay a fee and back taxes, Fox News reported. Some prominent voices in Trump''s base pushed back, warning that any amnesty deal would damage the Republican Party.

The comments come as Republicans prepare to hand control of both chambers of Congress to Democrats in January.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/b/b0/Arriving_at_Ellis_Island_LCCN97519082.jpg', 'Immigrants arriving at Ellis Island, New York, early 20th century (file). Photo: Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-10.sql', 7, 0, 'newsroom-assistant', '2026-11-10T10:45:00.000Z', '2026-11-10T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261110-immigration-deal-src1', 'bd-20261110-immigration-deal', 'White House doubles down after Trump angers base by floating illegal alien deal with Dems', 'https://www.foxnews.com/politics/white-house-doubles-down-trump-angers-base-floating-illegal-alien-deal-dems', 'Fox News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-10T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-10. Editor to confirm.', 'newsroom-assistant', '2026-11-10T10:45:00.000Z');
