INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261110-dana-white-briefing', 'trump-dana-white-white-house-briefing-press-secretary-joke-pete-rose-pardon', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'Trump brings UFC chief Dana White to the briefing room and says the press secretary offer was a joke', 'White told reporters on Monday, Nov. 9, that he has "zero political aspirations." Trump also repeated that he favors a posthumous pardon for Pete Rose.', 'President Trump made a surprise appearance in the White House briefing room on Monday, Nov. 9, with UFC chief executive Dana White, after reports that he had floated White as his press secretary, Fox News reported.

Trump said he suggested White after "a very bad press day" and called it a joke. "I was sort of kidding, and then they wrote the story as though I wasn''t kidding," he said, according to Fox News. Democracy Now reported that Trump had offered White the job before saying he was joking, and that the two were set to meet on Monday.

## White at the podium

White took questions from reporters and said, "I have zero political aspirations." He said he was at a fight in London when Trump called him about the idea, and that he never explicitly told Trump no, Fox News reported. He called Trump the toughest person he has ever met.

## Pete Rose

Trump also repeated at the briefing that he favors a posthumous pardon for Pete Rose, the former Cincinnati Reds star who was banned over betting on baseball, Fox News reported. Major League Baseball removed Rose and 16 others from its permanently ineligible list in 2025.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/c/c2/President_George_W._Bush_responds_to_questions_during_his_final_press_conference_in_the_James_S._Brady_Press_Briefing_Room_of_the_White_House.jpg', 'The James S. Brady Press Briefing Room at the White House, during a 2009 news conference (file). Photo: White House via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-10.sql', 6, 0, 'newsroom-assistant', '2026-11-10T10:45:00.000Z', '2026-11-10T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261110-dana-white-briefing-src1', 'bd-20261110-dana-white-briefing', 'Dana White denies interest in Trump press secretary role at briefing', 'https://www.foxnews.com/politics/dana-white-takes-questions-podium-during-white-house-briefing-trump', 'Fox News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-10T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-10. Editor to confirm.', 'newsroom-assistant', '2026-11-10T10:45:00.000Z');
