INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261110-dana-white-briefing-ev1', 'bd-20261110-dana-white-briefing', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-10T10:45:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261110-red-sox-zack-kelly', 'red-sox-release-zack-kelly-reliever-thanks-boston-after-five-seasons', 'newsroom', 'news_story', 'mlb', 'EDITORIAL_REVIEW', 0, 'Red Sox release reliever Zack Kelly, who thanks Boston after five seasons in the bullpen', 'Kelly, who missed the second half of 2026 with elbow inflammation, cleared waivers after being designated for assignment and is now a free agent.', 'The Red Sox have released right-hander Zack Kelly, who cleared waivers after Boston designated him for assignment at the start of the offseason, NESN and Sports Illustrated reported on Monday, Nov. 9. He is now a free agent.

Kelly thanked the club in a post on X. "What a ride!" he wrote, adding that he was grateful to have been part of "such a historic organization the last 6 years," NESN reported.

## His Boston career

Kelly pitched in 115 games for the Red Sox over five seasons after his debut on Aug. 29, 2022, going 8-8 with a 4.04 ERA and 127 strikeouts in 131 1/3 innings, according to NESN. His best season came in 2024, when he posted a 3.97 ERA in a career-high 49 appearances, Sports Illustrated reported.

In 2026, he had a 3.31 ERA in 17 appearances before Boston placed him on the 60-day injured list in July with right elbow inflammation. Kelly went undrafted and joined Boston on a minor league deal in 2021. Sports Illustrated reported that he will likely look for a minor league contract with a spring training invitation.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/4/4a/Red_Sox_at_spring_training,_Hot_Springs,_AR_(baseball)_LCCN2014691782.jpg', 'Red Sox players at spring training in Hot Springs, Ark., early 20th century (file). Photo: Bain News Service, Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-10.sql', 6, 0, 'newsroom-assistant', '2026-11-10T10:45:00.000Z', '2026-11-10T10:45:00.000Z');
