INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261110-bills-vikings', 'bills-beat-vikings-23-6-monday-night-football-james-cook-107-yards-wentz', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Bills 23, Vikings 6: James Cook runs for 107 yards as Buffalo''s defense holds Minnesota to 178 yards on Monday night', 'The Bills improved to 7-1 with the win in Minneapolis on Monday, Nov. 9. Carson Wentz completed 8 of 25 passes and had three turnovers.', 'The Buffalo Bills beat the Minnesota Vikings 23-6 at U.S. Bank Stadium on Monday, Nov. 9, ESPN reported. Buffalo improved to 7-1 and Minnesota fell to 6-2.

James Cook carried 31 times for 107 yards and added a late touchdown. Josh Allen completed 21 of 31 passes for 234 yards, threw a 25-yard touchdown pass to Keleki Latu before halftime and had one interception, according to ESPN. Tyler Bass made three field goals, extending his franchise-record streak to 24 in a row.

## Minnesota''s offense stalls

The Vikings scored all six of their points in the second quarter and finished with 178 yards. Starting in place of the injured Kyler Murray, Carson Wentz completed 8 of 25 passes for 81 yards and committed three turnovers, including a lost fumble near midfield on a backward pass, ESPN and VAVEL reported. Terrel Bernard and Dorian Williams intercepted him.

Vikings coach Kevin O''Connell took full responsibility for the offense''s performance, according to ESPN. Bills coach Joe Brady credited his team''s patience early, when the offense was slow to get going.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/e/e4/Flickr_-_Official_U.S._Navy_Imagery_-_Navy_parachutes_into_Buffalo_Bills_game.jpg', 'A U.S. Navy parachute team lands at a Buffalo Bills home game (file). Photo: U.S. Navy via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-10.sql', 5, 0, 'newsroom-assistant', '2026-11-10T10:45:00.000Z', '2026-11-10T10:45:00.000Z');
