INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261110-lakers-hawks', 'lakers-beat-hawks-124-114-doncic-32-points-10-assists-sixth-straight-win', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Luka Doncic posts 32 points and 10 assists as the Lakers beat the Hawks 124-114 for a sixth straight win', 'The NBA Cup game in Atlanta on Monday, Nov. 9, ended the Hawks'' four-game winning streak. Austin Reaves sat out with an illness.', 'Luka Doncic scored 32 points with 10 assists and eight rebounds as the Los Angeles Lakers beat the Atlanta Hawks 124-114 in an NBA Cup game in Atlanta on Monday, Nov. 9, the Associated Press reported via ABC News. The Lakers won their sixth game in a row and ended the Hawks'' four-game winning streak.

Doncic had been listed as questionable with lower back tightness before the game, CBS Sports reported. Sandro Mamukelashvili scored 23 points and made 5 of 8 three-pointers, Walker Kessler had 21 points and 10 rebounds in a return to the Atlanta area where he grew up, and Collin Sexton added 18 points off the bench. Los Angeles made 15 of 35 threes.

## Reaves sits

Austin Reaves missed the game with an illness, a day after scoring 43 points at Detroit, according to the AP.

## Hawks

CJ McCollum led Atlanta with 21 points off the bench, Nickeil Alexander-Walker scored 20 and Onyeka Okongwu had 16. Dyson Daniels, who guarded Doncic for much of the game, finished with 10 points, eight assists and four steals. The Lakers entered the game 9-2 and the Hawks 7-4, CBS Sports reported.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/e/ef/2010_NBA_Champion_Los_Angeles_Lakers_with_President_Obama.jpg', 'The 2010 NBA champion Los Angeles Lakers at the White House (file). Photo: White House via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-10.sql', 4, 0, 'newsroom-assistant', '2026-11-10T10:45:00.000Z', '2026-11-10T10:45:00.000Z');
